// ---------------------------------------------------------------------------
// Slots — owned by the mentor (`/me/slots`) or read for any mentor
// ---------------------------------------------------------------------------
mentors.get('/:uid/slots', async (c) => {
  try {
    await requireAuth(c);
    const m = await loadMentorByUid(c.env, c.req.param('uid'));
    if (!m) return c.json({ detail: 'Mentor not found' }, 404);
    const upcoming = (c.req.query('upcoming_only') || 'true').toLowerCase() === 'true';
    const sql = upcoming
      ? 'SELECT * FROM mentor_office_hour_slots WHERE mentor_id = ? AND is_cancelled = 0 AND ends_at >= ? ORDER BY starts_at ASC'
      : 'SELECT * FROM mentor_office_hour_slots WHERE mentor_id = ? ORDER BY starts_at DESC LIMIT 200';
    const rows = upcoming
      ? await c.env.DB.prepare(sql).bind(m.id, nowIso()).all<SlotRow>()
      : await c.env.DB.prepare(sql).bind(m.id).all<SlotRow>();
    const items: any[] = [];
    for (const s of (rows.results || []) as SlotRow[]) {
      items.push(slotDto(s, await takenForSlot(c.env, s.id)));
    }
    return c.json({ items });
  } catch (e) { return mapError(c, e); }
});

mentors.post('/me/slots', async (c) => {
  try {
    const user = await requireAuth(c);
    const m = await myMentor(c.env, user);
    if (!m) return c.json({ detail: 'Set up your mentor profile first' }, 400);
    const body = await c.req.json().catch(() => ({} as any));
    const starts = String(body.starts_at || '').trim();
    const ends = String(body.ends_at || '').trim();
    if (!starts || !ends) return c.json({ detail: 'starts_at and ends_at required' }, 400);
    if (new Date(ends).getTime() <= new Date(starts).getTime()) {
      return c.json({ detail: 'ends_at must be after starts_at' }, 400);
    }
    const capacity = Math.max(1, Math.min(20, Number(body.capacity || 1)));
    const meeting_url = body.meeting_url ? String(body.meeting_url).slice(0, 500) : null;
    const notes = body.notes ? String(body.notes).slice(0, 1000) : null;
    const uid = newUid();
    const r = await c.env.DB.prepare(
      `INSERT INTO mentor_office_hour_slots
        (uid, mentor_id, starts_at, ends_at, capacity, meeting_url, notes, is_cancelled, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?)`
    ).bind(uid, m.id, starts, ends, capacity, meeting_url, notes, nowIso()).run();
    const slot = await c.env.DB.prepare('SELECT * FROM mentor_office_hour_slots WHERE id = ?')
      .bind((r as any).meta?.last_row_id).first<SlotRow>();
    return c.json(slotDto(slot!));
  } catch (e) { return mapError(c, e); }
});

mentors.delete('/me/slots/:id', async (c) => {
  try {
    const user = await requireAuth(c);
    const m = await myMentor(c.env, user);
    if (!m) return c.json({ detail: 'Mentor profile required' }, 403);
    const id = Number(c.req.param('id'));
    const slot = await c.env.DB.prepare('SELECT * FROM mentor_office_hour_slots WHERE id = ?').bind(id).first<SlotRow>();
    if (!slot || slot.mentor_id !== m.id) return c.json({ detail: 'Slot not found' }, 404);
    await c.env.DB.prepare('UPDATE mentor_office_hour_slots SET is_cancelled = 1 WHERE id = ?').bind(id).run();
    // Cancel any open bookings on this slot.
    await c.env.DB.prepare(
      `UPDATE mentor_bookings SET status = 'cancelled', cancel_reason = COALESCE(cancel_reason, 'slot_cancelled'), updated_at = ?
       WHERE slot_id = ? AND status IN ('pending','confirmed')`
    ).bind(nowIso(), id).run();
    return c.json({ ok: true });
  } catch (e) { return mapError(c, e); }
});

// ---------------------------------------------------------------------------
// Booking
// ---------------------------------------------------------------------------
mentors.post('/slots/:id/book', async (c) => {
  try {
    const user = await requireAuth(c);
    // Task #6 — mentor booking is Growth-tier for founders.
    ensureTier(user, 'growth');
    if (!isFounder(user) && !isAdmin(user)) return c.json({ detail: 'Founder role required' }, 403);
    const slotId = Number(c.req.param('id'));
    const body = await c.req.json().catch(() => ({} as any));
    const slot = await c.env.DB.prepare('SELECT * FROM mentor_office_hour_slots WHERE id = ?').bind(slotId).first<SlotRow>();
    if (!slot || slot.is_cancelled) return c.json({ detail: 'Slot not available' }, 404);
    if (new Date(slot.starts_at).getTime() < Date.now()) {
      return c.json({ detail: 'Slot is in the past' }, 400);
    }
    const taken = await takenForSlot(c.env, slotId);
    if (taken >= slot.capacity) return c.json({ detail: 'Slot full' }, 409);
    const uid = newUid();
    try {
      const r = await c.env.DB.prepare(
        `INSERT INTO mentor_bookings
          (uid, slot_id, mentor_id, founder_user_id, topic, notes, status, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, 'pending', ?, ?)`
      ).bind(uid, slotId, slot.mentor_id, user.id,
             (body.topic || '').toString().slice(0, 200),
             (body.notes || '').toString().slice(0, 2000),
             nowIso(), nowIso()).run();
      // Re-check capacity after insert (D1 has no SELECT-FOR-UPDATE).
      const after = await takenForSlot(c.env, slotId);
      if (after > slot.capacity) {
        await c.env.DB.prepare(
          `UPDATE mentor_bookings SET status = 'cancelled', cancel_reason = 'capacity_race', updated_at = ?
           WHERE id = ?`
        ).bind(nowIso(), (r as any).meta?.last_row_id).run();
        return c.json({ detail: 'Slot full (race)' }, 409);
      }
      const b = await c.env.DB.prepare('SELECT * FROM mentor_bookings WHERE id = ?')
        .bind((r as any).meta?.last_row_id).first<BookingRow>();
      // Task #1 (Slack, 2026-05-10) — notify the mentor that a founder
      // has booked one of their slots. Best-effort; never blocks the booking.
      try {
        const mentorRow = await c.env.DB.prepare(
          'SELECT user_id, display_name FROM mentors WHERE id = ?'
        ).bind(slot.mentor_id).first<{ user_id: number | null; display_name: string | null }>();
        if (mentorRow?.user_id) {
          const { notify } = await import('../services/notify');
          await notify(c.env, {
            userId: mentorRow.user_id,
            type: 'mentor_session_booked',
            title: `New office-hours booking`,
            body: `${user.name || user.email} booked your slot starting ${slot.starts_at}.`,
            link: '/mentors',
            payload: { booking_uid: uid, slot_id: slotId },
            channels: ['in_app', 'email', 'slack'],
            category: 'mentor_session_booked',
          });
        }
      } catch (e) { console.warn('[mentors] notify mentor_session_booked failed', e); }
      return c.json(bookingDto(b!));
    } catch (e: any) {
      if (String(e?.message || e).includes('UNIQUE')) {
        return c.json({ detail: 'Already booked this slot' }, 409);
      }
      throw e;
    }
  } catch (e) { return mapError(c, e); }
});

